CREATE TABLE IF NOT EXISTS project_economic_models (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'NGN', acquisition_cost numeric(20,2) DEFAULT 0, legal_cost numeric(20,2) DEFAULT 0, development_cost numeric(20,2) DEFAULT 0, infrastructure_cost numeric(20,2) DEFAULT 0, operating_cost numeric(20,2) DEFAULT 0, financing_cost numeric(20,2) DEFAULT 0, contingency numeric(20,2) DEFAULT 0, projected_revenue numeric(20,2) DEFAULT 0, development_months integer, operating_months integer, exit_value numeric(20,2), assumptions jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());